'use strict';
(()=>{
 const stage=document.getElementById('presenterStage');if(!stage)return;
 const monitor=document.createElement('div');monitor.id='presenterMonitor';monitor.setAttribute('aria-label','Live view of the same race');
 const canvas=document.createElement('canvas');canvas.width=960;canvas.height=600;canvas.setAttribute('aria-label','Current racers, points and live racing camera');monitor.append(canvas);stage.prepend(monitor);
 const ctx=canvas.getContext('2d',{alpha:false});let last=0,frames=0,lastRound=null,lastNames=[];
 function draw(source,r){const now=performance.now();if(now-last<80||stage.hidden||!document.body.classList.contains('screen'))return;last=now;const w=canvas.width,h=canvas.height,header=104;ctx.fillStyle='#071b2b';ctx.fillRect(0,0,w,h);const count=r.settings.cars,cell=w/count;
  for(let i=0;i<count;i++){const p=r.slots[i];ctx.save();ctx.beginPath();ctx.rect(i*cell+3,3,cell-6,header-6);ctx.clip();ctx.fillStyle=r.carStyles?.[i]?.color||'#6ce9ff';ctx.fillRect(i*cell+3,header-5,cell-6,3);ctx.textAlign='center';ctx.fillStyle='#f6fcff';ctx.font='bold 23px Arial';const name=p?.name||'OPEN SLOT';ctx.fillText(name,(i+.5)*cell,35,cell-12);ctx.font='bold 21px Arial';ctx.fillStyle='#ffe59d';ctx.fillText('CAR '+(i+1)+' · '+Math.floor((p?.distance||0)/r.settings.step)+' PTS',(i+.5)*cell,72,cell-12);ctx.restore()}
  if(source?.width&&source?.height){const ratio=Math.min(w/source.width,(h-header)/source.height),dw=source.width*ratio,dh=source.height*ratio;const dx=(w-dw)/2,dy=header+(h-header-dh)/2;ctx.drawImage(source,dx,dy,dw,dh);ctx.save();ctx.beginPath();ctx.rect(dx,dy,dw,dh);ctx.clip();const bounds=source.getBoundingClientRect();for(const p of window.Race3D?.players||[]){if(p.label.hidden)continue;const box=p.label.getBoundingClientRect(),x=dx+(box.left-bounds.left+box.width/2)/bounds.width*dw,y=dy+(box.top-bounds.top+box.height/2)/bounds.height*dh,size=box.width/bounds.width*dw;ctx.save();ctx.beginPath();ctx.arc(x,y,size/2,0,Math.PI*2);ctx.fillStyle=r.carStyles?.[p.index]?.color||'#77e4f5';ctx.fill();ctx.clip();const photo=p.label.querySelector('img');if(photo?.complete&&photo.naturalWidth){ctx.drawImage(photo,x-size/2,y-size/2,size,size)}else{ctx.fillStyle='#071b2b';ctx.font='bold '+Math.round(size*.6)+'px Arial';ctx.textAlign='center';ctx.fillText((r.slots[p.index]?.name||'?').slice(0,1),x,y+size*.2)}ctx.restore()}ctx.fillStyle='#081a2ddd';ctx.fillRect(dx+4,dy+4,Math.min(dw-8,390),27);ctx.fillStyle='#fff3ad';ctx.textAlign='left';ctx.font='bold 18px Arial';ctx.fillText(document.querySelector('.race3d-pace-hud')?.textContent||'',dx+10,dy+24,Math.min(dw-20,370));ctx.restore()}
  ctx.fillStyle='#082033e8';ctx.fillRect(0,h-30,w,30);ctx.fillStyle='#d5fff5';ctx.font='bold 18px Arial';ctx.textAlign='left';ctx.fillText(window.raceRoundStage?.(r.round,r.settings.roundsPerRace).title||'LIVE RACE',15,h-9);ctx.textAlign='right';ctx.fillText(r.settings.paused?'PAUSED':!r.settings.running?'STOPPED':'LIVE RACE',w-15,h-9);lastRound=r.round;lastNames=r.slots.slice(0,count).map(p=>p?.name||'OPEN SLOT');frames++;
 }
 window.RaceHostMonitor={draw,get canvas(){return canvas},get frames(){return frames},get round(){return lastRound},get names(){return lastNames}};
})();
